package br.com.stockmanager.security;
import br.com.stockmanager.service.UserDetailsServiceImpl; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.authentication.WebAuthenticationDetailsSource; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.stereotype.Component; import java.io.IOException;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter{
 private final JwtService jwt; private final UserDetailsServiceImpl users; public JwtAuthenticationFilter(JwtService jwt,UserDetailsServiceImpl users){this.jwt=jwt;this.users=users;}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{String email=jwt.subject(h.substring(7));var details=users.loadUserByUsername(email);if(SecurityContextHolder.getContext().getAuthentication()==null)SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(details,null,details.getAuthorities()));}catch(JwtException|IllegalArgumentException e){SecurityContextHolder.clearContext();}}chain.doFilter(req,res);}
}
